impl<'de> Deserialize<'de> for RouteAnchor {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        struct V;
        impl<'de> Visitor<'de> for V {
            type Value = RouteAnchor;
            fn expecting(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                f.write_str("a RouteAnchor")
            }
            fn visit_str<E: serde::de::Error>(self, s: &str) -> Result<Self::Value, E> {
                Ok(match s {
                    _ => RouteAnchor::Unknown,
                })
            }
            fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<Self::Value, A::Error> {
                let Some(tag) = map.next_key::<String>()? else {
                    return Ok(RouteAnchor::Unknown);
                };
                let value = match tag.as_str() {
                    "Port" => RouteAnchor::Port(map.next_value()?),
                    "Strip" => {
                        let p: RouteAnchorStripPayload = map.next_value()?;
                        RouteAnchor::Strip {
                            lane: p.lane,
                            rack_id: p.rack_id,
                            role: p.role,
                            side: p.side,
                            slot: p.slot,
                            u_band: p.u_band,
                        }
                    }
                    "Edge" => {
                        let p: RouteAnchorEdgePayload = map.next_value()?;
                        RouteAnchor::Edge {
                            face: p.face,
                            rack_id: p.rack_id,
                            roof_hole_side: p.roof_hole_side,
                            side: p.side,
                        }
                    }
                    "Tray" => {
                        let p: RouteAnchorTrayPayload = map.next_value()?;
                        RouteAnchor::Tray {
                            slot: p.slot,
                            tray_id: p.tray_id,
                        }
                    }
                    "Point" => {
                        let p: RouteAnchorPointPayload = map.next_value()?;
                        RouteAnchor::Point {
                            pos: p.pos,
                        }
                    }
                    "RailHole" => {
                        let p: RouteAnchorRailHolePayload = map.next_value()?;
                        RouteAnchor::RailHole {
                            depth: p.depth,
                            height: p.height,
                            rack_id: p.rack_id,
                            side: p.side,
                        }
                    }
                    _ => {
                        map.next_value::<IgnoredAny>()?;
                        RouteAnchor::Unknown
                    }
                };
                while map.next_entry::<IgnoredAny, IgnoredAny>()?.is_some() {}
                Ok(value)
            }
        }
        d.deserialize_any(V)
    }
}

